import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int[] x = new int[6];
        int total = 0;

        for (int i = 0; i < 6; i++) {
            x[i] = sc.nextInt();
            total += x[i];
        }

        boolean possible = false;

        if (total % 3 == 0) {
            int target = total / 3;

            for (int single = 0; single < 6 && !possible; single++) {
                for (int a = 0; a < 6 && !possible; a++) {
                    if (a == single) continue;

                    for (int b = a + 1; b < 6 && !possible; b++) {
                        if (b == single) continue;

                        if (x[single] + x[a] + x[b] != target) continue;

                        int pairSum = 0;
                        for (int i = 0; i < 6; i++) {
                            if (i != single && i != a && i != b) {
                                pairSum += x[i];
                            }
                        }

                        if (pairSum == target) possible = true;
                    }
                }
            }
        }

        System.out.println(possible ? "S" : "N");
    }
}
